// @manicat-dependencies react-native-svg
import { useEffect, useRef, useState } from "react";
import { PanResponder, Pressable, StyleSheet, Text, View } from "react-native";
import type { StyleProp, TextStyle, ViewProps, ViewStyle } from "react-native";
import Svg, { Path } from "react-native-svg";
import { linePath } from "../lib/chart";
import { metrics, useTokens } from "../lib/rn-tokens";

export type InkColor = "black" | "blue" | "violet";
export type InkWidth = "fine" | "medium" | "bold";

export interface InkPoint {
  x: number;
  y: number;
}

export interface InkStroke {
  id: string;
  points: InkPoint[];
  color: InkColor;
  width: InkWidth;
}

export interface SignaturePadProps extends Omit<ViewProps, "children"> {
  signer?: string;
  hint?: string;
  defaultColor?: InkColor;
  defaultWidth?: InkWidth;
  onChange?: (strokes: InkStroke[]) => void;
  height?: number;
  /** Extend the inner, named parts of the pad: surface, line, hint or action. The React Native counterpart of `classNames`. */
  styles?: {
    surface?: StyleProp<ViewStyle>;
    line?: StyleProp<ViewStyle>;
    hint?: StyleProp<TextStyle>;
    action?: StyleProp<TextStyle>;
  };
}

const ink: Record<InkColor, string> = { black: "#111111", blue: "#1f5fd1", violet: "#6d3cc9" };
const thickness: Record<InkWidth, number> = { fine: 1.5, medium: 2.5, bold: 4 };

/** Draw with a finger or a stylus. The strokes are reported as plain points, so you can store them or render them yourself. */
export function SignaturePad({ signer, hint = "Sign above the line", defaultColor = "black", defaultWidth = "medium", onChange, height = 180, style, styles: parts, ...props }: SignaturePadProps) {
  const tokens = useTokens();
  const [strokes, setStrokes] = useState<InkStroke[]>([]);
  const [color, setColor] = useState(defaultColor);
  const [width, setWidth] = useState(defaultWidth);
  const live = useRef({ strokes, color, width, onChange });
  useEffect(() => {
    live.current = { strokes, color, width, onChange };
  });

  function commit(next: InkStroke[]) {
    setStrokes(next);
    live.current.onChange?.(next);
  }

  // eslint-disable-next-line react-hooks/refs
  const [pan] = useState(() =>
    PanResponder.create({
      onStartShouldSetPanResponder: () => true,
      onMoveShouldSetPanResponder: () => true,
      onPanResponderGrant: (event) => {
        const { color: c, width: w, strokes: all } = live.current;
        commit([...all, { id: `s-${all.length}-${Date.now()}`, color: c, width: w, points: [{ x: event.nativeEvent.locationX, y: event.nativeEvent.locationY }] }]);
      },
      onPanResponderMove: (event) => {
        const all = live.current.strokes;
        const current = all[all.length - 1];
        if (current) commit([...all.slice(0, -1), { ...current, points: [...current.points, { x: event.nativeEvent.locationX, y: event.nativeEvent.locationY }] }]);
      },
    }),
  );

  const empty = strokes.length === 0;

  return (
    <View {...props} style={[{ alignSelf: "stretch", gap: metrics.space[2] }, style]}>
      <View accessible accessibilityLabel={`Signature pad${signer ? ` for ${signer}` : ""}`} {...pan.panHandlers} style={[local.surface, { height, borderColor: tokens.border, backgroundColor: tokens.surface }, parts?.surface]}>
        <Svg width="100%" height={height} pointerEvents="none">
          {strokes.map((stroke) => (
            <Path key={stroke.id} d={linePath(stroke.points.map((point): [number, number] => [point.x, point.y]), "smooth") || `M${stroke.points[0].x},${stroke.points[0].y}`} fill="none" stroke={ink[stroke.color]} strokeWidth={thickness[stroke.width]} strokeLinecap="round" strokeLinejoin="round" />
          ))}
        </Svg>
        <View pointerEvents="none" style={[local.line, { backgroundColor: tokens.borderStrong }, parts?.line]} />
        {empty ? <Text pointerEvents="none" style={[local.hint, { color: tokens.textMuted }, parts?.hint]}>{hint}</Text> : null}
      </View>
      <View style={local.actions}>
        {(["black", "blue", "violet"] as const).map((name) => (
          <Pressable key={name} accessibilityRole="radio" accessibilityLabel={`${name} ink`} accessibilityState={{ checked: color === name }} onPress={() => setColor(name)} style={[local.swatch, { backgroundColor: ink[name], borderColor: color === name ? tokens.foreground : "transparent" }]} />
        ))}
        {(["fine", "medium", "bold"] as const).map((name) => (
          <Pressable key={name} accessibilityRole="radio" accessibilityLabel={`${name} pen`} accessibilityState={{ checked: width === name }} onPress={() => setWidth(name)} style={[local.pen, { backgroundColor: width === name ? tokens.surfaceMuted : "transparent" }]}>
            <View style={{ width: 18, height: thickness[name], borderRadius: 2, backgroundColor: tokens.foreground }} />
          </Pressable>
        ))}
        <View style={{ flex: 1 }} />
        <Pressable accessibilityRole="button" disabled={empty} onPress={() => commit(strokes.slice(0, -1))} style={{ opacity: empty ? 0.4 : 1 }}>
          <Text style={[{ color: tokens.textSecondary, fontSize: metrics.text.xs }, parts?.action]}>Undo</Text>
        </Pressable>
        <Pressable accessibilityRole="button" disabled={empty} onPress={() => commit([])} style={{ opacity: empty ? 0.4 : 1 }}>
          <Text style={[{ color: tokens.textSecondary, fontSize: metrics.text.xs }, parts?.action]}>Clear</Text>
        </Pressable>
      </View>
      {signer ? <Text style={{ color: tokens.textMuted, fontSize: metrics.text.xs }}>{signer}</Text> : null}
    </View>
  );
}

const local = StyleSheet.create({
  surface: { borderWidth: 1, borderRadius: 26, overflow: "hidden" },
  line: { position: "absolute", left: 24, right: 24, bottom: 36, height: 1 },
  hint: { position: "absolute", left: 0, right: 0, bottom: 12, textAlign: "center", fontSize: metrics.text.xs },
  actions: { flexDirection: "row", alignItems: "center", gap: metrics.space[3] },
  swatch: { width: 22, height: 22, borderRadius: 11, borderWidth: 2 },
  pen: { width: 28, height: 28, alignItems: "center", justifyContent: "center", borderRadius: 14 },
});

export default SignaturePad;

import { useColorScheme } from "react-native";

/** The Manicat UI design tokens as React Native values. Same names and meaning as registry/foundation.css. */
export interface ManicatTokens {
  background: string;
  surface: string;
  surfaceMuted: string;
  foreground: string;
  textSecondary: string;
  textMuted: string;
  border: string;
  borderStrong: string;
  accent: string;
  accentStrong: string;
  accentSubtle: string;
  success: string;
  warning: string;
  danger: string;
  controlOn: string;
  controlTrack: string;
  controlThumb: string;
  controlThumbOn: string;
  /** Four distinguishable colours for chart series, the counterpart of --series-1 to --series-4. */
  series: [string, string, string, string];
}

export const lightTokens: ManicatTokens = {
  background: "#ffffff",
  surface: "#ffffff",
  surfaceMuted: "#f6f6f6",
  foreground: "#1b1b1b",
  textSecondary: "#6e6e6e",
  textMuted: "#8f8f8f",
  border: "#ebebeb",
  borderStrong: "#c9c9c9",
  accent: "#4a4a4a",
  accentStrong: "#303030",
  accentSubtle: "rgba(74, 74, 74, 0.1)",
  success: "#1f8a4c",
  warning: "#b8741a",
  danger: "#d03b3b",
  controlOn: "#2c2c2c",
  controlTrack: "#e2e2e2",
  controlThumb: "#ffffff",
  controlThumbOn: "#ffffff",
  series: ["#1f7dcf", "#7128a5", "#e58f00", "#009e84"],
};

export const darkTokens: ManicatTokens = {
  background: "#2b2b2b",
  surface: "#303030",
  surfaceMuted: "#3c3c3c",
  foreground: "#f1f1f1",
  textSecondary: "#c4c4c4",
  textMuted: "#a0a0a0",
  border: "#454545",
  borderStrong: "#5c5c5c",
  accent: "#cfcfcf",
  accentStrong: "#e6e6e6",
  accentSubtle: "rgba(207, 207, 207, 0.13)",
  success: "#5fd48a",
  warning: "#f0b95c",
  danger: "#ff8a80",
  controlOn: "#ececec",
  controlTrack: "#515151",
  controlThumb: "#f4f4f4",
  controlThumbOn: "#2b2b2b",
  series: ["#55adff", "#9c37be", "#e66e00", "#00a861"],
};

/** Shape and rhythm shared by every component, in density-independent pixels. */
export const metrics = {
  radiusControl: 18,
  radiusPill: 9999,
  controlHeight: { sm: 36, md: 44, lg: 50 },
  space: { 1: 4, 2: 8, 3: 12, 4: 16, 5: 20 },
  text: { xs: 12, sm: 14, lg: 18 },
} as const;

/** The tokens for the device's current colour scheme. Wrap the app in your own provider if you manage the theme yourself. */
export function useTokens(): ManicatTokens {
  return useColorScheme() === "dark" ? darkTokens : lightTokens;
}

/**
 * Geometry shared by the chart ports (React Native with react-native-svg, Vue with inline SVG). Pure functions: they turn data
 * into scales, ticks and SVG path strings, and leave drawing to each framework.
 */

export type Point = [number, number];

export interface Scale {
  (value: number): number;
  domain: [number, number];
  range: [number, number];
}

export function linearScale(domain: [number, number], range: [number, number]): Scale {
  const [d0, d1] = domain;
  const [r0, r1] = range;
  const scale = ((value: number) => (d1 === d0 ? (r0 + r1) / 2 : r0 + ((value - d0) / (d1 - d0)) * (r1 - r0))) as Scale;
  scale.domain = domain;
  scale.range = range;
  return scale;
}

/** A tidy upper bound for a data maximum: 1, 2, 2.5, 5 or 10 times a power of ten. */
export function niceMax(max: number): number {
  if (max <= 0) return 1;
  const power = Math.pow(10, Math.floor(Math.log10(max)));
  const fraction = max / power;
  const step = fraction <= 1 ? 1 : fraction <= 2 ? 2 : fraction <= 2.5 ? 2.5 : fraction <= 5 ? 5 : 10;
  return step * power;
}

/** `count` evenly spaced tick values from 0 to a nice maximum. */
export function ticks(max: number, count = 4): number[] {
  const top = niceMax(max);
  return Array.from({ length: count + 1 }, (_, index) => (top / count) * index);
}

export const compact = (n: number) => new Intl.NumberFormat("en-US", { notation: "compact", maximumFractionDigits: 1 }).format(n);

/** A straight polyline, or a smooth curve through the points (monotone-ish Catmull-Rom converted to cubic Béziers). */
export function linePath(points: Point[], curve: "smooth" | "linear" = "smooth"): string {
  if (points.length === 0) return "";
  if (points.length === 1 || curve === "linear") return points.map(([x, y], index) => `${index ? "L" : "M"}${x.toFixed(2)},${y.toFixed(2)}`).join("");
  let d = `M${points[0][0].toFixed(2)},${points[0][1].toFixed(2)}`;
  for (let index = 0; index < points.length - 1; index += 1) {
    const p0 = points[index - 1] ?? points[index];
    const p1 = points[index];
    const p2 = points[index + 1];
    const p3 = points[index + 2] ?? p2;
    const c1: Point = [p1[0] + (p2[0] - p0[0]) / 6, p1[1] + (p2[1] - p0[1]) / 6];
    const c2: Point = [p2[0] - (p3[0] - p1[0]) / 6, p2[1] - (p3[1] - p1[1]) / 6];
    d += `C${c1[0].toFixed(2)},${c1[1].toFixed(2)} ${c2[0].toFixed(2)},${c2[1].toFixed(2)} ${p2[0].toFixed(2)},${p2[1].toFixed(2)}`;
  }
  return d;
}

/** The area between a line and the baseline `y0`. */
export function areaPath(points: Point[], y0: number, curve: "smooth" | "linear" = "smooth"): string {
  if (points.length === 0) return "";
  const last = points[points.length - 1];
  return `${linePath(points, curve)}L${last[0].toFixed(2)},${y0.toFixed(2)}L${points[0][0].toFixed(2)},${y0.toFixed(2)}Z`;
}

/** A band between an upper and a lower line, for stacked areas. */
export function bandPath(upper: Point[], lower: Point[], curve: "smooth" | "linear" = "smooth"): string {
  if (upper.length === 0) return "";
  const back = [...lower].reverse();
  return `${linePath(upper, curve)}L${back[0][0].toFixed(2)},${back[0][1].toFixed(2)}${linePath(back, curve).replace(/^M[^CL]*/, "")}Z`;
}

/** A ring segment from `a0` to `a1` radians (0 is 12 o'clock, clockwise). */
export function arcPath(cx: number, cy: number, outer: number, inner: number, a0: number, a1: number): string {
  const sweep = Math.min(a1 - a0, Math.PI * 2 - 0.0001);
  const end = a0 + sweep;
  const point = (r: number, a: number): Point => [cx + r * Math.sin(a), cy - r * Math.cos(a)];
  const [x0, y0] = point(outer, a0);
  const [x1, y1] = point(outer, end);
  const [x2, y2] = point(inner, end);
  const [x3, y3] = point(inner, a0);
  const large = sweep > Math.PI ? 1 : 0;
  return `M${x0.toFixed(2)},${y0.toFixed(2)}A${outer},${outer} 0 ${large} 1 ${x1.toFixed(2)},${y1.toFixed(2)}L${x2.toFixed(2)},${y2.toFixed(2)}A${inner},${inner} 0 ${large} 0 ${x3.toFixed(2)},${y3.toFixed(2)}Z`;
}

export interface Rect {
  x: number;
  y: number;
  width: number;
  height: number;
}

/** Squarified treemap: lays `values` out in `rect`, keeping cells close to square. Returns one rect per value, in input order. */
export function squarify(values: number[], rect: Rect): Rect[] {
  const total = values.reduce((sum, value) => sum + value, 0);
  const out: Rect[] = new Array(values.length);
  if (total <= 0) return values.map(() => ({ ...rect, width: 0, height: 0 }));
  const order = values.map((value, index) => ({ value, index })).sort((a, b) => b.value - a.value);
  let free = { ...rect };
  let remaining = total;
  let row: typeof order = [];

  const worst = (items: typeof order, side: number, scale: number) => {
    const sum = items.reduce((s, item) => s + item.value * scale, 0);
    const max = Math.max(...items.map((item) => item.value * scale));
    const min = Math.min(...items.map((item) => item.value * scale));
    return Math.max((side * side * max) / (sum * sum), (sum * sum) / (side * side * min));
  };

  const place = (items: typeof order, scale: number) => {
    const sum = items.reduce((s, item) => s + item.value * scale, 0);
    const horizontal = free.width >= free.height;
    const thickness = sum / (horizontal ? free.height : free.width);
    let offset = 0;
    for (const item of items) {
      const length = (item.value * scale) / thickness;
      out[item.index] = horizontal ? { x: free.x, y: free.y + offset, width: thickness, height: length } : { x: free.x + offset, y: free.y, width: length, height: thickness };
      offset += length;
    }
    free = horizontal ? { x: free.x + thickness, y: free.y, width: free.width - thickness, height: free.height } : { x: free.x, y: free.y + thickness, width: free.width, height: free.height - thickness };
    remaining -= items.reduce((s, item) => s + item.value, 0);
  };

  for (const item of order) {
    const scale = (free.width * free.height) / remaining;
    const side = Math.min(free.width, free.height);
    if (row.length === 0 || worst([...row, item], side, scale) <= worst(row, side, scale)) row.push(item);
    else {
      place(row, scale);
      row = [item];
    }
  }
  if (row.length) place(row, (free.width * free.height) / remaining);
  return out;
}
